import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.CountingOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TarArchiveOutputStream.write method.
 * Focuses on maximizing branch and line coverage.
 */
public class TarArchiveOutputStream_write_TriageGen1Test {

    private ByteArrayOutputStream baos;
    private TarArchiveOutputStream tarOut;
    private static final int RECORD_SIZE = 512;

    @Before
    public void setUp() throws IOException {
        baos = new ByteArrayOutputStream();
        // Using custom record size of 512 to make testing predictable
        tarOut = new TarArchiveOutputStream(baos, RECORD_SIZE, RECORD_SIZE);
    }









    @Test
    public void testWrite_MixedAssemblyAndLargeWrite() throws IOException {
        // 1. Start with small write (fills assemBuf)
        // 2. Follow with a write that is larger than recordBuf.length
        // This tests the complex logic of updating offsets and remaining counts

        int totalSize = RECORD_SIZE * 4;
        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        entry.setSize(totalSize);
        tarOut.putArchiveEntry(entry);

        byte[] data = new byte[totalSize];

        // 1. Fill assemBuf with 50 bytes
        tarOut.write(data, 0, 50);

        // 2. Write enough to trigger the assembly flush AND have extra left over
        // (assemLen + numToWrite) >= recordBuf.length
        // 50 + 600 = 650. 650 >= 512. 
        // aLen = 512 - 50 = 462.
        // numToWrite becomes 600 - 462 = 138.
        // Then it enters the while loop.
        tarOut.write(data, 0, 600);

        // 3. Write the remaining bytes
        int remaining = totalSize - 50 - 600;
        tarOut.write(data, 0, remaining);

        tarOut.closeArchiveEntry();
        Assert.assertTrue(tarOut.getBytesWritten() >= totalSize);
    }


}

